const AUDIO=CARDS.filter(c=>c.hasAudio);
const EXTRA=CARDS.filter(c=>!c.hasAudio);
const STORAGE='english-c1-speaking-unit1-v2',OLD='c1-speaking-studio-v1';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const norm=s=>String(s??'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[’']/g,'').replace(/[^a-z0-9]+/g,' ').trim();
const dateNow=()=>{let d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')};
const addDays=n=>{let d=new Date();d.setDate(d.getDate()+n);return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')};
const today=dateNow();
let state={days:{},srs:{},favorite:[],preferences:{dailySize:8,cardDirection:'es-en'}};
try{const stored=JSON.parse(localStorage.getItem(STORAGE)||'null');if(stored?.days)state=stored}catch(e){}
state.preferences??={};
state.preferences.dailySize=[6,8,10,12].includes(Number(state.preferences.dailySize))?Number(state.preferences.dailySize):8;
state.preferences.cardDirection=['es-en','en-es'].includes(state.preferences.cardDirection)?state.preferences.cardDirection:'es-en';
// Prioridad real: repasar lo pendiente, luego SB 1.1 -> WB track 1 -> vocabulario adicional SB/WB.
// Cuando se incorporen grabaciones 1.2, 1.3... se podrán insertar aquí por orden de pista.
function chooseDaily(){
 const prior=new Set(Object.entries(state.days||{}).filter(([d])=>d!==today).flatMap(([_,v])=>v.selected||[]));
 const due=CARDS.filter(c=>state.srs[c.id]?.due<=today);
 const freshAudio=AUDIO.filter(c=>!state.srs[c.id]&&!prior.has(c.id));
 const freshBook=EXTRA.filter(c=>!state.srs[c.id]&&!prior.has(c.id));
 const remaining=CARDS.filter(c=>!state.srs[c.id]);
 return [...due,...freshAudio,...freshBook,...remaining,...CARDS].filter((v,i,a)=>a.indexOf(v)===i).slice(0,state.preferences.dailySize).map(c=>c.id)
}
if(!state.days[today]){
 let previous=null;try{previous=JSON.parse(localStorage.getItem(OLD)||'null')}catch(e){}
 let migrated=previous?.simpleFlow?.days?.[today]?.selected?.filter(id=>CARDS.some(c=>c.id===id))||[];
 state.days[today]={selected:migrated.length?migrated:chooseDaily(),learn:{},plays:{},speaking:null,test:{},testDate:null};
 if(previous?.cards){CARDS.forEach(c=>{let x=c.legacyIndex===undefined?null:previous.cards['1-'+c.legacyIndex];if(!x||state.srs[c.id])return;state.srs[c.id]={level:x.level??-1,due:x.due||today,successDays:x.correctDays||[],seen:x.seen||0}})}
}
let day=state.days[today];day.selected??=chooseDaily();day.learn??={};day.plays??={};day.test??={};
const save=()=>{try{localStorage.setItem(STORAGE,JSON.stringify(state))}catch(e){notice('No se pudo guardar el progreso en este navegador. Puedes exportarlo desde Progreso.')}};
const picked=()=>CARDS.filter(c=>day.selected.includes(c.id));
const cardDirection=()=>state.preferences.cardDirection;
